import { Box } from "@chakra-ui/react";
import { useMemo } from "react";
import { ReactFlowProvider } from "reactflow";
import { Canvas } from "../../canvas/Canvas";
import { CanvasContextProvider } from "../../CanvasContext";
import type { FlowEdge, FlowNode, SkillBlock } from "../../types";
import { skillBlockToGraph } from "../../utils/skill-flow-import";
import { FlowErrorBoundary } from "../FlowErrorBoundary";

function findShortestPath(edges: FlowEdge[], start: string, end: string): string[] | null {
  const queue: string[][] = [[start]];
  const visited = new Set<string>();
  while (queue.length > 0) {
    const path = queue.shift()!;
    const node = path[path.length - 1];
    if (node === end) return path;
    if (!visited.has(node)) {
      visited.add(node);
      for (const edge of edges) {
        if (edge.sourceId === node) queue.push([...path, edge.targetId]);
      }
    }
  }
  return null;
}

/**
 * Highlights the edges and nodes actually traversed in this block, derived from
 * the ordered step trail (conversation events filtered to this block's flow id).
 * Mirrors the collectHighlightedEdges logic in Flow.tsx: direct edges are
 * preferred; BFS shortest path fills gaps where the engine reports steps that
 * have no single-hop edge between them in the graph.
 */
export function collectHighlightedEdges(
  nodes: FlowNode[],
  edges: FlowEdge[],
  stepTrail: string[],
): { highlightedEdges: FlowEdge[]; highlightedNodes: FlowNode[] } {
  const seen = new Set<string>();
  const highlightedEdges: FlowEdge[] = [];
  const highlightedNodes: FlowNode[] = [];
  // Mantle enters an ordered block through a `call` frame whose first stack
  // step is the block's first real step, so — unlike the CALM stack — the trail
  // never passes through the synthetic START. Prepend it so the entry edge
  // (START → first step) highlights too, matching the CALM flow canvas.
  const trail =
    stepTrail.length > 0 && stepTrail[0] !== "START" ? ["START", ...stepTrail] : stepTrail;
  let previousStep: string | null = trail.length > 0 ? trail[0] : null;

  const addNode = (id: string) => {
    const n = nodes.find((node) => node.id === id);
    if (n && !highlightedNodes.includes(n)) highlightedNodes.push(n);
  };

  for (let i = 0; i < trail.length - 1; i++) {
    const from = trail[i];
    const to = trail[i + 1];
    const key = `${from}->${to}`;
    if (seen.has(key)) continue;

    const direct = edges.find((e) => e.sourceId === from && e.targetId === to);
    if (direct) {
      seen.add(key);
      highlightedEdges.push(direct);
      addNode(from);
      addNode(to);
      previousStep = to;
      continue;
    }

    let path = findShortestPath(edges, from, to);
    if (!path && previousStep) {
      path = findShortestPath(edges, previousStep, to);
    }
    if (!path) continue;

    seen.add(key);
    for (let j = 0; j < path.length - 1; j++) {
      const edge = edges.find((e) => e.sourceId === path[j] && e.targetId === path[j + 1]);
      if (edge) {
        const pathKey = `${edge.sourceId}->${edge.targetId}`;
        if (!seen.has(pathKey)) {
          seen.add(pathKey);
          highlightedEdges.push(edge);
          addNode(edge.sourceId);
          addNode(edge.targetId);
        }
        previousStep = path[j + 1];
      }
    }
  }

  return { highlightedEdges, highlightedNodes };
}

interface SkillBlockCanvasProps {
  readonly blockId: string;
  readonly block: SkillBlock;
  /** Ids a `call:` step may target (block flow ids + skill ids), for call labels. */
  readonly callTargetIds: string[];
  /** Step id to focus as the current position, when this block is active. */
  readonly activeStepId: string | null;
  /** Ordered step ids visited in this block, derived from conversation events. */
  readonly stepTrail: string[];
}

/**
 * The inline flow visualization of one expanded ordered block: the block's
 * step graph on the shared canvas, with the actual traversed path highlighted.
 */
export function SkillBlockCanvas({
  blockId,
  block,
  callTargetIds,
  activeStepId,
  stepTrail,
}: SkillBlockCanvasProps) {
  const { nodes, edges } = useMemo(
    () => skillBlockToGraph(block, callTargetIds),
    [block, callTargetIds],
  );

  const { highlightedNodes, highlightedEdges } = useMemo(
    () => collectHighlightedEdges(nodes, edges, stepTrail),
    [nodes, edges, stepTrail],
  );

  return (
    <Box flex="1" minHeight="300px" data-testid="skill-block-canvas">
      <FlowErrorBoundary
        shortLabel="Could not render block"
        longLabel="An error occurred while visualizing this ordered block"
      >
        <ReactFlowProvider>
          <CanvasContextProvider
            title={blockId}
            initNodes={nodes}
            initEdges={edges}
            highlightedNodes={highlightedNodes}
            highlightedEdges={highlightedEdges}
            activeNodeId={activeStepId ?? stepTrail.at(-1) ?? null}
            fitViewWhenUnfocused
          >
            <Canvas embedded />
          </CanvasContextProvider>
        </ReactFlowProvider>
      </FlowErrorBoundary>
    </Box>
  );
}
